/**
 * Fail the build when rendered metadata or the sitemap breaks the SEO rules.
 * Redirect stubs generated by Astro are skipped. Inbound-link shortages warn only.
 *
 * Usage: node scripts/seo-check.mjs [distDir]
 */
import fs from 'node:fs';
import path from 'node:path';

const distDir = process.argv[2] ?? 'dist';
const SITE = 'https://studenteb5.com';
const failures = [];
const warnings = [];

function walk(dir, extension) {
  if (!fs.existsSync(dir)) return [];
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...walk(full, extension));
    else if (entry.name.endsWith(extension)) files.push(full);
  }
  return files;
}

function decode(value) {
  return value
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&#x27;|&apos;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function metaContent(html, name) {
  const tags = html.match(/<meta\b[^>]*>/gi) ?? [];
  const found = [];
  for (const tag of tags) {
    const key = tag.match(/\b(?:name|property)=["']([^"']+)["']/i)?.[1];
    if (key?.toLowerCase() !== name.toLowerCase()) continue;
    const quoted = tag.match(/\bcontent="([^"]*)"/i) ?? tag.match(/\bcontent='([^']*)'/i);
    found.push(decode(quoted?.[1] ?? ''));
  }
  return found;
}

function isRedirect(html) {
  return /http-equiv=["']refresh["']/i.test(html) || /<title>\s*Redirecting to:/i.test(html);
}

function pagePath(file) {
  const rel = path.relative(distDir, file).replace(/\\/g, '/');
  const urlPath = `/${rel.replace(/index\.html$/, '').replace(/\.html$/, '')}`;
  return urlPath.replace(/\/$/, '') || '/';
}

function expectedCanonical(urlPath) {
  return urlPath === '/' ? SITE : `${SITE}${urlPath}`;
}

const pages = [];
for (const file of walk(distDir, '.html')) {
  const html = fs.readFileSync(file, 'utf8');
  if (isRedirect(html)) continue;
  const urlPath = pagePath(file);
  const titles = [...html.matchAll(/<title>([^<]*)<\/title>/gi)].map((match) => decode(match[1]));
  const descriptions = metaContent(html, 'description');
  const h1s = [...html.matchAll(/<h1\b[^>]*>/gi)];
  const canonicalTag = html.match(/<link\b[^>]*rel=["']canonical["'][^>]*>/i)?.[0] ?? '';
  const canonical = decode(canonicalTag.match(/href=["']([^"']+)["']/i)?.[1] ?? '');
  const ogUrls = metaContent(html, 'og:url');
  const robots = metaContent(html, 'robots').join(' ');
  const jsonBlocks = [...html.matchAll(/<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
  pages.push({
    urlPath,
    html,
    titles,
    descriptions,
    h1Count: h1s.length,
    canonical,
    ogUrls,
    noindex: /noindex/i.test(robots),
    jsonBlocks: jsonBlocks.map((match) => match[1].trim()),
  });
}

const titleOwners = new Map();
const descriptionOwners = new Map();

for (const page of pages) {
  const where = page.urlPath;
  if (page.titles.length !== 1) failures.push(`${where}: expected 1 title, found ${page.titles.length}`);
  if (page.descriptions.length !== 1) {
    failures.push(`${where}: expected 1 meta description, found ${page.descriptions.length}`);
  }
  if (page.h1Count !== 1) failures.push(`${where}: expected 1 h1, found ${page.h1Count}`);

  const title = page.titles[0] ?? '';
  const description = page.descriptions[0] ?? '';
  if (title.length < 30 || title.length > 60) {
    failures.push(`${where}: title length ${title.length} (30-60): ${title}`);
  }
  if (description.length < 70 || description.length > 160) {
    failures.push(`${where}: description length ${description.length} (70-160): ${description}`);
  }
  if (title) {
    const prior = titleOwners.get(title);
    if (prior) failures.push(`${where}: duplicate title also used on ${prior}`);
    else titleOwners.set(title, where);
  }
  if (description) {
    const prior = descriptionOwners.get(description);
    if (prior) failures.push(`${where}: duplicate description also used on ${prior}`);
    else descriptionOwners.set(description, where);
  }

  const expected = expectedCanonical(where);
  if (!page.canonical) failures.push(`${where}: canonical missing`);
  else if (page.canonical !== expected) {
    failures.push(`${where}: canonical ${page.canonical} != ${expected}`);
  }
  if (page.ogUrls.length !== 1 || page.ogUrls[0] !== page.canonical) {
    failures.push(`${where}: og:url ${page.ogUrls.join(', ') || '(missing)'} != canonical`);
  }

  for (const block of page.jsonBlocks) {
    try {
      JSON.parse(block);
    } catch (error) {
      failures.push(`${where}: JSON-LD does not parse (${error.message})`);
    }
  }
}

const sitemapFiles = walk(distDir, '.xml').filter((file) => !/sitemap-index/i.test(path.basename(file)));
const sitemapPaths = [];
for (const file of sitemapFiles) {
  const xml = fs.readFileSync(file, 'utf8');
  for (const match of xml.matchAll(/<loc>([^<]+)<\/loc>/gi)) {
    const loc = decode(match[1]);
    if (/\/sitemap/i.test(loc)) continue;
    try {
      const url = new URL(loc);
      const urlPath = url.pathname.replace(/\/$/, '') || '/';
      sitemapPaths.push(urlPath);
    } catch {
      failures.push(`sitemap loc is not a URL: ${loc}`);
    }
  }
}

const noindexPaths = new Set(pages.filter((page) => page.noindex).map((page) => page.urlPath));
for (const urlPath of sitemapPaths) {
  if (noindexPaths.has(urlPath)) failures.push(`${urlPath}: noindex page is in the sitemap`);
}

const upcomingDeadline = /(before|by)\s+Sept(ember|\.)?\s+30,?\s+2026/i;
const indexable = new Set(sitemapPaths.filter((urlPath) => !noindexPaths.has(urlPath)));

function visibleText(html) {
  const body = html.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i)?.[1] ?? html;
  return decode(
    body
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' '),
  );
}

for (const page of pages) {
  if (!indexable.has(page.urlPath)) continue;
  for (const sentence of visibleText(page.html).split(/(?<=[.!?])\s+/)) {
    if (upcomingDeadline.test(sentence) && !/on or before/i.test(sentence)) {
      warnings.push(`${page.urlPath}: upcoming September 30, 2026 wording: ${sentence.slice(0, 180)}`);
    }
  }
}

function linksTo(html, urlPath) {
  const hrefs = html.match(/href=["']([^"']+)["']/gi) ?? [];
  for (const raw of hrefs) {
    const href = raw.match(/href=["']([^"']+)["']/i)?.[1] ?? '';
    if (!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:')) continue;
    let target = '';
    if (href.startsWith(SITE)) {
      try {
        target = new URL(href).pathname;
      } catch {
        continue;
      }
    } else if (href.startsWith('/')) {
      target = href.split(/[?#]/)[0];
    } else continue;
    target = target.replace(/\/$/, '') || '/';
    if (target === urlPath) return true;
  }
  return false;
}

for (const urlPath of new Set(sitemapPaths)) {
  let inbound = 0;
  for (const page of pages) {
    if (page.urlPath === urlPath) continue;
    if (linksTo(page.html, urlPath)) inbound += 1;
  }
  if (inbound < 3) warnings.push(`${urlPath}: ${inbound} inbound internal links`);
}

if (warnings.length) {
  console.warn(`SEO warnings (${warnings.length}), not failing the build:`);
  for (const warning of warnings) console.warn(`  ${warning}`);
}

if (failures.length) {
  console.error(`SEO check failed (${failures.length}):`);
  for (const failure of failures) console.error(`  ${failure}`);
  process.exit(1);
}

console.log(`SEO check passed (${pages.length} pages, ${sitemapPaths.length} sitemap URLs).`);
